package com.samadhansetu.Service;
import com.samadhansetu.Repository.DepartmentRepository; import com.samadhansetu.Repository.UniversityRepository; import com.samadhansetu.dto.*; import com.samadhansetu.model.entity.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class DepartmentService{private final DepartmentRepository repo;private final UniversityRepository universities;public DepartmentResponseDto create(DepartmentRequestDto r){University u=universities.findById(r.getUniversityId()).orElseThrow(()->new IllegalArgumentException("University not found: "+r.getUniversityId()));if(r.getCode()!=null&&repo.existsByUniversityIdAndCode(u.getId(),r.getCode()))throw new IllegalArgumentException("Department code already exists in university");return map(repo.save(Department.builder().name(r.getName()).code(r.getCode()).university(u).build()));}public DepartmentResponseDto get(Long id){return map(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Department not found: "+id)));}public List<DepartmentResponseDto> all(){return repo.findAll().stream().map(this::map).toList();}public List<DepartmentResponseDto> byUniversity(Long id){return repo.findByUniversityId(id).stream().map(this::map).toList();}public List<DepartmentResponseDto> search(String name){return repo.findByNameContainingIgnoreCase(name).stream().map(this::map).toList();}public DepartmentResponseDto update(Long id,DepartmentRequestDto r){Department d=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Department not found: "+id));University u=universities.findById(r.getUniversityId()).orElseThrow(()->new IllegalArgumentException("University not found: "+r.getUniversityId()));d.setName(r.getName());d.setCode(r.getCode());d.setUniversity(u);return map(repo.save(d));}public void delete(Long id){if(!repo.existsById(id))throw new IllegalArgumentException("Department not found: "+id);repo.deleteById(id);}private DepartmentResponseDto map(Department d){return DepartmentResponseDto.builder().id(d.getId()).name(d.getName()).code(d.getCode()).universityId(d.getUniversity().getId()).universityName(d.getUniversity().getName()).build();}}
